import { Scheduler } from "march/components/scheduler"

// bu ayın gökyüzü takvimi: ay evreleri ve bir meteor yağmuru, salt okunur ay görünümünde
const iso = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`
const day = (n: number) => { const d = new Date(); d.setDate(n); return iso(d) }
const sky = [
  { id: "new", title: "🌑 Yeni ay", start: day(3), end: day(3), allDay: true, color: "brand-purple" as const },
  { id: "first", title: "🌓 İlk dördün", start: day(10), end: day(10), allDay: true, color: "brand-blue" as const },
  { id: "full", title: "🌕 Dolunay", start: day(17), end: day(17), allDay: true, color: "brand-gold" as const },
  { id: "last", title: "🌗 Son dördün", start: day(24), end: day(24), allDay: true, color: "brand-blue" as const },
  { id: "meteor", title: "☄️ Meteor yağmuru", start: day(12), end: day(14), allDay: true, color: "brand-pink" as const },
]

export function MoonPhases() {
  return <Scheduler label="Gökyüzü takvimi" events={sky} view="month" editable={false} help={false} height={420} views={false} />
}

import { Scheduler } from "march/components/scheduler"
import { Card } from "march/ui"

// bir kliniğin randevu takvimi: boş saate sürükleyince randevu açılır, sürükleyerek taşınır, tıklayınca ayrıntısı yazılır
const iso = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`
const monday = () => { const d = new Date(); d.setDate(d.getDate() - ((d.getDay() + 6) % 7)); return d }
const at = (dayOffset: number, time: string) => { const d = monday(); d.setDate(d.getDate() + dayOffset); return `${iso(d)}T${time}` }
type Booking = { id: string; title: string; start: string; end: string; location?: string; color?: "brand-blue" | "brand-green" | "brand-orange" }

export function ClinicBookings() {
  let $list: Booking[] = [
    { id: "b1", title: "Ayşe K. · kontrol", start: at(0, "09:00"), end: at(0, "09:30"), location: "Oda 1", color: "brand-blue" },
    { id: "b2", title: "Mehmet T. · diş taşı", start: at(1, "11:00"), end: at(1, "12:00"), location: "Oda 2", color: "brand-green" },
    { id: "b3", title: "Zeynep A. · dolgu", start: at(2, "14:30"), end: at(2, "15:30"), location: "Oda 1", color: "brand-orange" },
  ]
  let $note = "Boş bir saate sürükleyerek randevu açın"
  let n = 0
  return <Card title="Randevular" subtitle={() => $note}>
    <Scheduler label="Klinik randevuları" events={() => $list} view="week" step={30} weekends={false} startHour={8} height={460}
      onCreate={(r: { start: string; end: string; allDay: boolean }) => { $list = [...$list, { id: `n${++n}`, title: "Yeni randevu", start: r.start, end: r.end, color: "brand-orange" }]; $note = "Yeni randevu eklendi" }}
      onChange={(e: Booking, next: { start: string; end: string }) => { $list = $list.map((x) => (x.id === e.id ? { ...x, start: next.start, end: next.end } : x)); $note = `${e.title} taşındı` }}
      onSelect={(e: Booking) => $note = `${e.title} · ${e.location ?? "oda yok"}`} />
  </Card>
}

import { Scheduler } from "march/components/scheduler"
import { Button } from "march/ui"

// Scheduler'ın bütün özellikleri bir arada: events, view + onView, date + onDate, onChange, onCreate, onSelect, step,
// hourHeight, startHour, weekends, editable, height, locale, toolbar, views, todayButton, nowLine, help, renderEvent,
// labels, animate, label, class
const iso = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`
const today = iso(new Date())
type Ev = { id: string; title: string; start: string; end: string; allDay?: boolean; location?: string; color?: "brand-purple" | "brand-gold" }

export function SchedulerLab() {
  let $view = "week"
  let $date = today
  let $locale = "tr"
  let $log = "—"
  let $events: Ev[] = [
    { id: "a", title: "Tasarım incelemesi", start: `${today}T10:00`, end: `${today}T11:00`, location: "Stüdyo", color: "brand-purple" },
    { id: "b", title: "Yayın günü", start: today, end: today, allDay: true, color: "brand-gold" },
  ]
  return <div sx={{ flex: "col", gap: 2 }}>
    <div sx={{ flex: ["row", "wrap"], gap: 2 }}>
      <Button size="sm" on:click={() => $view = $view === "week" ? "day" : "week"}>{() => `Görünüm: ${$view}`}</Button>
      <Button size="sm" on:click={() => $locale = $locale === "tr" ? "en-US" : "tr"}>{() => `Dil: ${$locale}`}</Button>
      <Button size="sm" on:click={() => $date = today}>Bugüne dön</Button>
    </div>
    <p sx={{ text: "sm", color: "muted" }}>{() => `Tarih: ${$date} · Son olay: ${$log}`}</p>
    <Scheduler label="Laboratuvar takvimi" class="lab-sch" events={() => $events}
      view={() => $view as "week"} onView={(v: string) => $view = v}
      date={() => $date} onDate={(d: string) => $date = d}
      step={15} hourHeight={44} startHour={9} weekends editable height={380} locale={() => $locale}
      toolbar views={["week", "day"]} todayButton nowLine animate
      help="Sürükleyin, kenarından boyutlandırın, boş saate sürükleyip ekleyin."
      labels={{ allDay: "Gün boyu", today: "Bugün", more: (n: number) => `+${n} tane` }}
      renderEvent={(e: Ev, info: { time: string }) => <span><b>{e.title}</b><br /><small>{info.time}{e.location ? ` · ${e.location}` : ""}</small></span>}
      onCreate={(r: { start: string; end: string }) => { $events = [...$events, { id: `n${$events.length}`, title: "Yeni", start: r.start, end: r.end }]; $log = "eklendi" }}
      onChange={(e: Ev, r: { start: string; end: string }) => { $events = $events.map((x) => (x.id === e.id ? { ...x, ...r } : x)); $log = `${e.title} taşındı` }}
      onSelect={(e: Ev) => $log = `${e.title} seçildi`} />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { SchedulerLab } from "./SchedulerLab.tsx"

// SchedulerLab'in testleri: kaydedince Testler sekmesinde çalışır
test("takvim sınıfını ve kendi ipucunu alır", () => {
  const s = renderTest(() => <SchedulerLab />)
  expect(s.get(".lab-sch")).not.toBe(null)
  expect(s.sees("boş saate sürükleyip ekleyin")).toBe(true)
})

test("kendi içeriği: etkinlik başlığı ve yeri birlikte yazılır", () => {
  const s = renderTest(() => <SchedulerLab />)
  expect(s.sees("Tasarım incelemesi")).toBe(true)
  expect(s.sees("Stüdyo")).toBe(true)
})

test("görünüm düğmesi haftadan güne geçer", async () => {
  const s = renderTest(() => <SchedulerLab />)
  await s.click("Görünüm: week")
  expect(s.sees("Görünüm: day")).toBe(true)
})

test("dil düğmesi takvimin dilini değiştirir (lang)", async () => {
  const s = renderTest(() => <SchedulerLab />)
  expect(s.get(".lab-sch")?.getAttribute("lang")).toBe("tr")
  await s.click("Dil: tr")
  expect(s.get(".lab-sch")?.getAttribute("lang")).toBe("en-US")
})
